/**
 * Live visitor coordinates only. Not lum_get_map_data — that ships 500 past
 * rows with page_url and user_agent, ~41 KB, for two numbers.
 * last_seen is written with current_time('mysql'), so the cutoff must be too.
 */
function er_cover_live_points() {

	global $wpdb;
	$table = $wpdb->prefix . 'er_live_visitors';

	$cutoff = date( 'Y-m-d H:i:s', current_time( 'timestamp' ) - 15 * MINUTE_IN_SECONDS );

	$rows = $wpdb->get_results( $wpdb->prepare(
		"SELECT latitude, longitude FROM {$table}
		  WHERE last_seen >= %s
		    AND latitude IS NOT NULL AND longitude IS NOT NULL
		  LIMIT 40",
		$cutoff
	) );

	$out = array();
	foreach ( (array) $rows as $r ) {
		// 2dp ≈ 1km: enough for a dot, and no more precise than needed.
		$out[] = array( round( (float) $r->latitude, 2 ), round( (float) $r->longitude, 2 ) );
	}

	wp_send_json_success( $out );
}
add_action( 'wp_ajax_er_cover_live', 'er_cover_live_points' );
add_action( 'wp_ajax_nopriv_er_cover_live', 'er_cover_live_points' );


